const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});

const pdfKey = binaryKeys.find(k => {
  const b = item.binary[k];
  return (b.mimeType || '').includes('pdf') || (b.fileName || '').toLowerCase().endsWith('.pdf');
}) || binaryKeys[0];

if (!pdfKey) {
  throw new Error('Kein PDF-Anhang in der Mail gefunden.');
}

const pdfBinary = item.binary[pdfKey];

// PDF als base64 auslesen (n8n speichert binary als base64 intern)
const base64Content = pdfBinary.data;
const pdfName = pdfBinary.fileName || 'rechnung.pdf';

// emailData Struktur die ai_extract_worker.py erwartet
const emailData = {
  from: item.json.from || '',
  subject: item.json.subject || '',
  attachments: [
    {
      name: pdfName,
      contentType: 'application/pdf',
      content: base64Content
    }
  ]
};

return [{ json: emailData }];
